import{_ as o,C as i,o as e,c as s,a2 as a,b as l,w as r,a as n,E as c,a7 as h}from"./chunks/framework.ClrTBeVd.js";const _=JSON.parse('{"title":"ui-forge 验收验证与任务诊断","description":"","frontmatter":{"title":"ui-forge 验收验证与任务诊断","outline":"deep","publish":true},"headers":[],"relativePath":"ai/ui-forge-validation-diagnostics.md","filePath":"ai/ui-forge-validation-diagnostics.md","lastUpdated":1790144657000}'),p={name:"ai/ui-forge-validation-diagnostics.md"};function b(f,t,g,E,u,m){const d=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="ui-forge-验收验证与任务诊断" tabindex="-1">ui-forge 验收验证与任务诊断 <a class="header-anchor" href="#ui-forge-验收验证与任务诊断" aria-label="Permalink to &quot;ui-forge 验收验证与任务诊断&quot;">​</a></h1><p>模型说“完成了”，不代表页面真的能交付。ui-forge 把验收证据和运行诊断分开：前者看页面结果，后者看任务过程。</p><h2 id="页面如何验收" tabindex="-1">页面如何验收 <a class="header-anchor" href="#页面如何验收" aria-label="Permalink to &quot;页面如何验收&quot;">​</a></h2><p>页面需要从工程、交互和视觉三个方面检查，并保留对应证据：</p><table tabindex="0"><thead><tr><th>层次</th><th>证据</th><th>解决的问题</th></tr></thead><tbody><tr><td>工程</td><td>类型检查、构建和相关测试的输出</td><td>对应检查是否通过</td></tr><tr><td>交互</td><td>真实浏览器中的操作结果和测试记录</td><td>点击、输入、取消和恢复是否符合要求</td></tr><tr><td>视觉</td><td>参考图、浏览器截图及按需生成的差异图</td><td>布局、样式和页面状态是否符合设计</td></tr></tbody></table><p>任务规则要求 Codex 运行相关工程检查，再在浏览器中验证页面；发现问题后修改代码，并复查受影响的部分。交付时说明已验证、失败、未验证和受阻的项目，并附上测试输出、截图或报告。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/.agents/skills/ui-forge-d2c/SKILL.md" target="_blank" rel="noreferrer">源码：D2C 验证与交付要求</a></p><p>这不是 Server 在每轮结束后自动执行的固定流水线。具体工具由 Codex 根据任务选择，<code>completed</code> 只表示本轮执行结束，不能代替验收结论。</p><h2 id="截图如何比较" tabindex="-1">截图如何比较 <a class="header-anchor" href="#截图如何比较" aria-label="Permalink to &quot;截图如何比较&quot;">​</a></h2><h3 id="先保证两张图可以对照" tabindex="-1">先保证两张图可以对照 <a class="header-anchor" href="#先保证两张图可以对照" aria-label="Permalink to &quot;先保证两张图可以对照&quot;">​</a></h3><p>只有任务明确要求严格像素验收时，才使用比较脚本。未启用时，仍需按设计规则进行浏览器视觉检查。</p><p>比较前，需要确认参考图可靠，两图的像素尺寸一致，并对应相同的视口和页面状态。截图前应等待字体与图片加载完成，并禁用动画。例如，参考图展示了悬停状态，实际截图也应通过真实操作进入该状态。脚本只读取图片，不能替浏览器判断这些条件是否满足；缺少条件时应说明受阻原因。</p><h3 id="按像素差异判断" tabindex="-1">按像素差异判断 <a class="header-anchor" href="#按像素差异判断" aria-label="Permalink to &quot;按像素差异判断&quot;">​</a></h3><p>脚本使用 <strong>Python + Pillow 图像处理库</strong>，不是让 AI 给图片打分。它将两张图转成 RGBA，即红、绿、蓝和透明度四个通道，再比较同一位置各通道的数值差异：</p>',13)),(e(),l(h,null,{default:r(()=>[c(d,{id:"mermaid-86",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%E5%8F%82%E8%80%83%E5%9B%BE%20%2B%20%E5%AE%9E%E9%99%85%E6%88%AA%E5%9B%BE%5D%20--%3E%20B%5B%E7%BB%9F%E4%B8%80%E5%83%8F%E7%B4%A0%E6%A0%BC%E5%BC%8F%20RGBA%5D%0A%20%20B%20--%3E%20C%7B%E5%B0%BA%E5%AF%B8%E7%9B%B8%E5%90%8C%3F%7D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20D%5Bdimension_mismatch%5D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20E%5B%E6%8C%89%E9%80%9A%E9%81%93%E8%AE%A1%E7%AE%97%E5%B7%AE%E5%BC%82%5D%0A%20%20E%20--%3E%20F%5B%E7%BB%9F%E8%AE%A1%E5%B7%AE%E5%BC%82%E5%83%8F%E7%B4%A0%E5%92%8C%E7%9B%B8%E8%BF%9E%E5%8C%BA%E5%9F%9F%5D%0A%20%20F%20--%3E%20G%5B%E6%8C%89%E9%98%88%E5%80%BC%E5%88%A4%E5%AE%9A%5D%0A%20%20G%20--%3E%20H%5B%E5%B7%AE%E5%BC%82%E5%9B%BE%20%2B%20JSON%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>脚本不会自动缩放或裁切图片，尺寸不一致时直接判为失败。尺寸相同时，只要某个像素的任意通道差值超过容差，就把它计为差异像素，再看两个指标：</p><ul><li><strong>全图差异像素比例</strong>：整体有多少像素不同。</li><li><strong>最大连通区域占比</strong>：最大一块相连差异占全图的比例，用来发现集中在局部的问题。</li></ul><p>启用严格像素验收，且任务未指定其他阈值时，内置设计规则采用以下默认值：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td>通道容差</td><td>8</td><td>任意通道差值大于 8，该像素就算不同</td></tr><tr><td>全图差异像素比例上限</td><td>1%</td><td>差异像素占比不得超过 1%</td></tr><tr><td>最大连通区域占比上限</td><td>0.1%</td><td>最大一块相连差异不得超过全图的 0.1%</td></tr></tbody></table><p>这些是规则约定，调用脚本时仍需显式传入，并非脚本自行填入的默认参数。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/instructions/design.md#L85" target="_blank" rel="noreferrer">源码：严格像素验收规则</a></p><p>脚本保存差异图，并向终端输出 JSON 比较结果，由调用方保存为报告；尺寸不一致时只报告失败，不生成差异图。<strong>比较通过只说明满足这组像素阈值</strong>，不能换算成“设计还原度”，也不能替代交互和工程检查。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/.agents/skills/ui-forge-d2c/scripts/compare_screenshots.py" target="_blank" rel="noreferrer">源码：截图比较脚本</a></p><details class="details custom-block"><summary>相连区域怎么算，返回码怎么看</summary><p>脚本通过广度优先搜索（BFS）统计相连区域：上下左右和四个斜角相邻的差异像素归为同一块，即“八邻域”。报告记录区域的位置、尺寸和面积，但不会识别按钮或文字等组件。</p><p>返回码 <code>0</code> 表示比较通过，<code>1</code> 表示未通过，<code>2</code> 表示参数、依赖或读写错误。</p></details><h2 id="任务异常如何排查" tabindex="-1">任务异常如何排查 <a class="header-anchor" href="#任务异常如何排查" aria-label="Permalink to &quot;任务异常如何排查&quot;">​</a></h2><p>任务失败、耗时异常，或需要核对运行配置时，可以打开页面的“任务诊断”，也可以使用 CLI 的 <code>diagnostics TASK_ID</code>。两种入口读取同一份诊断摘要，还可以导出 JSON 供排查使用。</p><table tabindex="0"><thead><tr><th>想了解什么</th><th>查看哪些信息</th></tr></thead><tbody><tr><td>任务使用了什么配置</td><td>模型、Codex 版本、运行配置和规则指纹</td></tr><tr><td>哪些执行环节出了问题</td><td>轮次状态、错误类别、工具完成和失败统计、子任务摘要</td></tr><tr><td>执行花了多少时间和 Token</td><td>轮次耗时、已记录的工具耗时和 Token 用量</td></tr></tbody></table><p>诊断提供排查线索，不会自动解释所有失败原因，也不会替用户重跑任务。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/diagnostics/taskDiagnostics.ts" target="_blank" rel="noreferrer">源码：诊断报告生成</a></p><h3 id="数字的统计范围" tabindex="-1">数字的统计范围 <a class="header-anchor" href="#数字的统计范围" aria-label="Permalink to &quot;数字的统计范围&quot;">​</a></h3><p>报告包含主会话和子任务摘要，但并不是所有数字都汇总了它们：</p><ul><li>轮次和工具统计来自主线程，子代理另列摘要。</li><li>Token 使用主线程最后一次观测到的累计值，不重复累加通知，也不汇总子线程。</li><li>工具可能并行执行，因此不能把工具耗时之和当作整轮执行耗时。</li><li>未采集到的信息显示未知，不补成零，也不用当前规则冒充历史规则。</li></ul><p>报告只输出预先允许的字段，不包含需求正文、规则全文、代码、命令输出、MCP 参数或审批凭据。要查看具体执行内容，仍需回到任务记录。</p><details class="details custom-block"><summary>诊断数据如何读取</summary><p><code>SessionService.readDiagnostics()</code> 根据任务索引定位会话，用 <code>thread/read</code> 读取主线程历史，再用 <code>thread/list</code> 查找子线程，并合并独立保存的运行配置、规则指纹和 Token 观测。</p><p>查询不调用 <code>thread/resume</code> 或启动新轮次；必要时仍会建立 Codex 通信连接。主线程历史读取失败时直接报错；子线程查询或辅助元数据不可用时，可以返回报告并标注缺失信息，不会改走会话恢复流程。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L273" target="_blank" rel="noreferrer">源码：诊断读取</a></p></details><details class="details custom-block"><summary>ui-forge 自身如何验证</summary><p>下面是工具本身的测试覆盖，不是生成页面的验收结果：</p><table tabindex="0"><thead><tr><th>测试</th><th>检查内容</th></tr></thead><tbody><tr><td><a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/src/imageScripts.test.ts" target="_blank" rel="noreferrer">比较器测试</a></td><td>相同图、对角相连差异、尺寸不符和无效阈值</td></tr><tr><td><a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/diagnostics/sessionDiagnostics.test.ts" target="_blank" rel="noreferrer">Server 诊断测试</a></td><td>不恢复或启动会话、Token 累计值更新、敏感内容过滤和元数据失败</td></tr><tr><td><a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-webview/e2e/task-diagnostics.spec.ts" target="_blank" rel="noreferrer">Webview E2E</a></td><td>诊断弹窗、导出、失败重试和窄屏交互</td></tr><tr><td><a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/src/codexClient.live.test.ts" target="_blank" rel="noreferrer">live 协议测试</a></td><td>真实 Codex 的编码、审批、停止和恢复链路</td></tr></tbody></table><p>具体执行结果应以对应测试记录为准。比较器测试缺少 Python/Pillow 时会跳过，live 测试需要显式启用。这些测试不能直接证明页面还原质量或效率提升；评估实际效果需要固定任务集、模型、规则和环境，再对照通过率、失败原因、耗时和 Token。</p></details>',17))])}const A=o(p,[["render",b]]);export{_ as __pageData,A as default};
